// The rig and view showing this drawing (as stored, unmirrored), or null.
inline const doom_stock_rig3d *doom_stock_rig3d_for(const char *name, int w, int h, const unsigned char *pixels,
                                                    const doom_rig3d_view **view)
{
    for (const doom_stock_rig3d &r : doom_stock_rig3d_table) {
        if (!r.sprite) break;
        for (const doom_rig3d_view &v : r.views) {
            if (!v.name || strcmp(v.name, name) || v.width != w || v.height != h) continue;
            unsigned hash = 2166136261u;
            for (size_t i = 0; i < (size_t)w * h * 2; ++i) hash = (hash ^ pixels[i]) * 16777619u;
            if (hash != v.hash) return nullptr;
            *view = &v;
            return &r;
        }
    }
    return nullptr;
}

